import { resolve } from 'node:path';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { createDatabase, createPool, redactDatabaseUrl } from './connection';
import { loadEnvFile } from './load-env-file';

/** Folder with the SQL migrations generated by drizzle-kit (`pnpm db:generate`). */
export const MIGRATIONS_FOLDER = resolve(__dirname, '../../drizzle');

export const DEFAULT_DATABASE_URL = 'postgres://streaming:streaming@localhost:5432/streaming_dev';

export async function runMigrations(databaseUrl: string): Promise<void> {
  const pool = createPool(databaseUrl);
  try {
    await migrate(createDatabase(pool), { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await pool.end();
  }
}

async function main(): Promise<void> {
  loadEnvFile();
  const databaseUrl = process.env.DATABASE_URL ?? DEFAULT_DATABASE_URL;
  await runMigrations(databaseUrl);
  console.log(`Migrations applied to ${redactDatabaseUrl(databaseUrl)}`);
}

if (require.main === module) {
  main().catch((error: unknown) => {
    console.error('Migration failed:', error instanceof Error ? error.message : error);
    process.exit(1);
  });
}
